const assert = require('assert');
const fs = require('fs');
const os = require('os');
const path = require('path');
const { execFileSync, spawn, spawnSync } = require('child_process');

const LEDGER = path.join(__dirname, '..', '..', 'skills', 'story-lifecycle', 'scripts', 'ledger.js');
const { resolveLedgerPath } = require(LEDGER);

const EPIC = `# Epic: Auth flow

**Slug:** auth-flow
**Status:** ready

## Stories

<!-- Derived from story files — regenerated by status and on every transition -->
| ID | Title | Status |
| --- | --- | --- |
`;

function story(id, title, { sprint = 'unassigned', status = 'todo', points = 3 } = {}) {
  return `# Story: ${title}\n\n**ID:** ${id}\n**Epic:** auth-flow\n**Sprint:** ${sprint}\n**Status:** ${status}\n**Points:** ${points}\n`;
}

function run(root, args, env = {}) {
  const r = spawnSync(process.execPath, [LEDGER, ...args, '--root', root], { encoding: 'utf8', env: { ...process.env, ...env } });
  return { code: r.status, out: r.stdout ? JSON.parse(r.stdout) : null, err: r.stderr };
}

function runAsync(root, args) {
  return new Promise((resolve) => {
    const child = spawn(process.execPath, [LEDGER, ...args, '--root', root]);
    let out = '';
    child.stdout.on('data', (d) => { out += d; });
    child.on('close', (code) => resolve({ code, out }));
  });
}

function writeJson(root, name, value) {
  const file = path.join(root, name);
  fs.writeFileSync(file, JSON.stringify(value));
  return file;
}

function newRepo() {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), 'story-ledger-'));
  execFileSync('git', ['init', '-q', root]);
  assert.strictEqual(run(root, ['init']).code, 0);
  const input = writeJson(root, 'epic.json', { create: { 'epics/auth-flow.md': EPIC } });
  assert.strictEqual(run(root, ['apply', '--input', input]).code, 0);
  return root;
}

function createStories(root, titles, tag = 'batch') {
  const { ids } = run(root, ['allocate', '--epic', 'auth-flow', '--count', String(titles.length)]).out;
  const create = Object.fromEntries(ids.map((id, i) => [`${id}.md`, story(id, titles[i])]));
  return { ids, input: writeJson(root, `${tag}.json`, { create }) };
}

const read = (root, rel) => fs.readFileSync(path.join(root, '.stories', rel), 'utf8');
const storyFiles = (root) => fs.readdirSync(path.join(root, '.stories')).filter((f) => /-\d+\.md$/.test(f)).sort();

// One full create-stories run (allocate + apply) in a separate process.
const WRITER = `
const { execFileSync } = require('child_process');
const fs = require('fs');
const [ledger, root, tag] = process.argv.slice(1);
const run = (...a) => JSON.parse(execFileSync(process.execPath, [ledger, ...a, '--root', root]));
const { ids } = run('allocate', '--epic', 'auth-flow', '--count', '3');
const create = Object.fromEntries(ids.map((id) => [id + '.md',
  '# Story: ' + tag + ' ' + id + '\\n\\n**ID:** ' + id + '\\n**Epic:** auth-flow\\n**Sprint:** unassigned\\n**Status:** todo\\n**Points:** 1\\n']));
fs.writeFileSync(root + '/' + tag + '.json', JSON.stringify({ create }));
run('apply', '--input', root + '/' + tag + '.json');
`;

const tests = [
  ['create-stories writes story files and regenerates the epic table', () => {
    const root = newRepo();
    const { ids, input } = createStories(root, ['Login', 'Logout']);
    assert.deepStrictEqual(ids, ['auth-flow-1', 'auth-flow-2']);
    assert.strictEqual(run(root, ['apply', '--input', input]).code, 0);
    assert.ok(read(root, 'epics/auth-flow.md').includes('| auth-flow-2 | Logout | todo |'));
    assert.ok(fs.existsSync(path.join(root, '.stories', '.gitignore')));
  }],

  ['two concurrent writers get distinct IDs and neither overwrites the other', async () => {
    const root = newRepo();
    const codes = await Promise.all(['a', 'b'].map((tag) => new Promise((resolve) => {
      spawn(process.execPath, ['-e', WRITER, LEDGER, root, tag], { stdio: 'inherit' }).on('close', resolve);
    })));
    assert.deepStrictEqual(codes, [0, 0]);
    const files = storyFiles(root);
    assert.strictEqual(files.length, 6, `expected 6 distinct story files, got ${files}`);
    const epic = read(root, 'epics/auth-flow.md');
    for (const f of files) assert.ok(epic.includes(`| ${f.slice(0, -3)} |`), `epic table missing ${f}`);
    assert.deepStrictEqual(run(root, ['status']).out.drift, []);
  }],

  ['a held lock makes the second writer wait, fail cleanly, then succeed on retry', async () => {
    const root = newRepo();
    const { input } = createStories(root, ['Login']);
    const lock = path.join(root, '.stories', '.lock');
    fs.writeFileSync(lock, JSON.stringify({ pid: process.pid, host: os.hostname(), at: 'now' }));
    fs.mkdirSync(path.join(root, '.stories', '.txn'));
    assert.strictEqual(run(root, ['status']).out.recoveryPending, false, 'in-flight batch of a live writer is not interrupted');
    const blocked = await runAsync(root, ['apply', '--input', input, '--wait-ms', '200']);
    assert.strictEqual(blocked.code, 3, 'expected lock-timeout exit code');
    assert.deepStrictEqual(storyFiles(root), []);
    fs.rmSync(lock);
    assert.strictEqual(run(root, ['apply', '--input', input]).code, 0);
    assert.deepStrictEqual(storyFiles(root), ['auth-flow-1.md']);
  }],

  ['creating an existing story ID is refused without overwrite', () => {
    const root = newRepo();
    const { ids, input } = createStories(root, ['Login']);
    assert.strictEqual(run(root, ['apply', '--input', input]).code, 0);
    const again = writeJson(root, 'again.json', { create: { [`${ids[0]}.md`]: story(ids[0], 'Clobber') } });
    assert.strictEqual(run(root, ['apply', '--input', again]).code, 4);
    assert.ok(read(root, `${ids[0]}.md`).includes('Login'));
  }],

  ['unallocated story IDs are refused', () => {
    const root = newRepo();
    const input = writeJson(root, 'raw.json', { create: { 'auth-flow-9.md': story('auth-flow-9', 'Raw') } });
    assert.notStrictEqual(run(root, ['apply', '--input', input]).code, 0);
    assert.deepStrictEqual(storyFiles(root), []);
  }],

  ['an interrupted batch is rolled back completely by the next writer', () => {
    const root = newRepo();
    const before = read(root, 'epics/auth-flow.md');
    const { input } = createStories(root, ['A', 'B', 'C']);
    const crashed = run(root, ['apply', '--input', input], { STORY_LEDGER_CRASH_AFTER: '2' });
    assert.strictEqual(crashed.code, 70);
    assert.strictEqual(storyFiles(root).length, 2, 'fixture must leave a partial batch on disk');
    assert.strictEqual(run(root, ['status']).out.recoveryPending, true);
    assert.strictEqual(run(root, ['recover']).out.rolledBack, 4);
    assert.deepStrictEqual(storyFiles(root), []);
    assert.strictEqual(read(root, 'epics/auth-flow.md'), before);
    assert.ok(!fs.existsSync(path.join(root, '.stories', '.lock')));
  }],

  ['plan-sprint assigns stories and derives the sprint table and total', () => {
    const root = newRepo();
    const { ids, input } = createStories(root, ['Login', 'Logout']);
    run(root, ['apply', '--input', input]);
    const sprint = '# Sprint 1\n\n## Stories\n\n<!-- Derived from story files — regenerated by status and on every transition -->\n| ID | Title | Points | Status |\n| --- | --- | --- | --- |\n\n## Total Points: 0\n';
    const plan = writeJson(root, 'plan.json', {
      create: { 'sprints/sprint-1.md': sprint },
      update: Object.fromEntries(ids.map((id, i) => [`${id}.md`, story(id, ['Login', 'Logout'][i], { sprint: '1', points: 5 })])),
    });
    assert.strictEqual(run(root, ['apply', '--input', plan]).code, 0);
    const s = read(root, 'sprints/sprint-1.md');
    assert.ok(s.includes('| auth-flow-1 | Login | 5 | todo |'));
    assert.ok(s.includes('## Total Points: 10'));
  }],

  ['status reports drift read-only; reconcile repairs the derived tables', () => {
    const root = newRepo();
    const { ids, input } = createStories(root, ['Login']);
    run(root, ['apply', '--input', input]);
    fs.writeFileSync(path.join(root, '.stories', `${ids[0]}.md`), story(ids[0], 'Login', { status: 'in-progress' }));
    const epicBefore = read(root, 'epics/auth-flow.md');
    assert.deepStrictEqual(run(root, ['status']).out.drift, ['epics/auth-flow.md']);
    assert.strictEqual(read(root, 'epics/auth-flow.md'), epicBefore, 'status must not write');
    assert.strictEqual(run(root, ['reconcile']).code, 0);
    assert.ok(read(root, 'epics/auth-flow.md').includes('| auth-flow-1 | Login | in-progress |'));
  }],

  ['git worktrees of one clone share ID allocation', () => {
    const root = newRepo();
    execFileSync('git', ['-C', root, '-c', 'user.email=t@t', '-c', 'user.name=t', 'commit', '-q', '--allow-empty', '-m', 'init']);
    const wt = `${root}-wt`;
    execFileSync('git', ['-C', root, 'worktree', 'add', '-q', wt]);
    run(wt, ['init']);
    run(wt, ['apply', '--input', writeJson(wt, 'epic.json', { create: { 'epics/auth-flow.md': EPIC } })]);
    const a = run(root, ['allocate', '--epic', 'auth-flow', '--count', '2']).out.ids;
    const b = run(wt, ['allocate', '--epic', 'auth-flow', '--count', '2']).out.ids;
    assert.deepStrictEqual([...a, ...b], ['auth-flow-1', 'auth-flow-2', 'auth-flow-3', 'auth-flow-4']);
  }],

  ['concurrent allocation from two worktrees never hands out the same ID', async () => {
    const root = newRepo();
    execFileSync('git', ['-C', root, '-c', 'user.email=t@t', '-c', 'user.name=t', 'commit', '-q', '--allow-empty', '-m', 'init']);
    const wt = `${root}-wt`;
    execFileSync('git', ['-C', root, 'worktree', 'add', '-q', wt]);
    run(wt, ['init']);
    run(wt, ['apply', '--input', writeJson(wt, 'epic.json', { create: { 'epics/auth-flow.md': EPIC } })]);
    // Each worktree has its own lock, so only the shared exclusive-create markers prevent duplicates.
    const results = await Promise.all(Array.from({ length: 32 }, (_, i) => runAsync(i % 2 ? wt : root, ['allocate', '--epic', 'auth-flow', '--count', '5'])));
    const ids = results.flatMap((r) => JSON.parse(r.out).ids);
    assert.strictEqual(ids.length, 160);
    assert.strictEqual(new Set(ids).size, 160, 'duplicate story IDs allocated across worktrees');
  }],

  ['ledger paths are confined to .stories/ file shapes', () => {
    const dir = path.join(os.tmpdir(), '.stories');
    for (const bad of ['../x-1.md', 'epics/../../x.md', 'Auth-1.md', 'a/b-1.md', 'epics/a.txt', 'sprints/sprint-0.md', '/abs-1.md']) {
      assert.throws(() => resolveLedgerPath(dir, bad), /invalid ledger path/, bad);
    }
    assert.ok(resolveLedgerPath(dir, 'epics\\auth-flow.md').endsWith(path.join('epics', 'auth-flow.md')));
  }],
];

(async () => {
  console.log('\n=== Testing story-lifecycle ledger behaviour ===\n');
  let passed = 0;
  let failed = 0;
  for (const [name, fn] of tests) {
    try {
      await fn();
      console.log(`  ✓ ${name}`);
      passed++;
    } catch (error) {
      console.log(`  ✗ ${name}`);
      console.log(`    Error: ${error.message}`);
      failed++;
    }
  }
  console.log(`\nResults: Passed: ${passed}, Failed: ${failed}`);
  process.exit(failed > 0 ? 1 : 0);
})();
